package com.example.starter.calibration.service;

import java.math.BigDecimal;
import java.util.List;

import com.example.starter.calibration.api.dto.CertificateResponse;
import com.example.starter.calibration.api.dto.MeasurementResponse;
import com.example.starter.calibration.api.dto.ReleaseRecordResponse;
import com.example.starter.calibration.api.dto.SessionEntryResponse;
import com.example.starter.calibration.api.dto.SessionResponse;
import com.example.starter.calibration.model.CalibrationSession;
import com.example.starter.calibration.model.Certificate;
import com.example.starter.calibration.model.Measurement;
import com.example.starter.calibration.model.MeasurementStatus;
import com.example.starter.calibration.model.ReleaseRecord;

/**
 * 领域模型到响应 DTO 的映射。
 */
final class DtoMapper {

    private DtoMapper() {
    }

    /** 十进制输出：去掉多余尾零，零统一输出 "0"。 */
    static String format(BigDecimal value) {
        BigDecimal stripped = value.stripTrailingZeros();
        if (stripped.compareTo(BigDecimal.ZERO) == 0) {
            return "0";
        }
        return stripped.toPlainString();
    }

    /** 可空十进制输出：null 原样返回 null。 */
    static String formatOrNull(BigDecimal value) {
        return value == null ? null : format(value);
    }

    static CertificateResponse toResponse(Certificate cert) {
        return new CertificateResponse(
                cert.id(),
                cert.instrumentId(),
                cert.validFrom(),
                cert.validTo(),
                cert.certType().name(),
                formatOrNull(cert.a()),
                formatOrNull(cert.b()),
                formatOrNull(cert.slope()),
                formatOrNull(cert.upOffset()),
                formatOrNull(cert.downOffset()),
                cert.revoked(),
                cert.revokedAt(),
                cert.createdAt());
    }

    static MeasurementResponse toResponse(Measurement m, boolean certificateRevoked,
                                          List<ReleaseRecord> releases) {
        boolean usable = m.status() == MeasurementStatus.RELEASED && !certificateRevoked;
        return new MeasurementResponse(
                m.id(),
                m.measurementKey(),
                m.instrumentId(),
                m.measuredAt(),
                format(m.rawReading()),
                format(m.lowerLimit()),
                format(m.upperLimit()),
                m.submittedBy(),
                m.certificateId(),
                format(m.computedValue()),
                m.displayValue().toPlainString(),
                m.passed(),
                m.status().name(),
                usable,
                m.createdAt(),
                releases.stream().map(DtoMapper::toResponse).toList());
    }

    static ReleaseRecordResponse toResponse(ReleaseRecord record) {
        return new ReleaseRecordResponse(record.batchId(), record.releasedBy(), record.releasedAt());
    }

    static SessionResponse toResponse(CalibrationSession session, List<Measurement> entries) {
        return new SessionResponse(
                session.id(),
                session.sessionKey(),
                session.instrumentId(),
                session.certificateId(),
                format(session.lowerLimit()),
                format(session.upperLimit()),
                session.status().name(),
                session.version(),
                session.createdBy(),
                session.createdAt(),
                session.closedAt(),
                entries.stream().map(DtoMapper::toEntryResponse).toList());
    }

    static SessionEntryResponse toEntryResponse(Measurement m) {
        return new SessionEntryResponse(
                m.id(),
                m.measurementKey(),
                m.sessionSeq(),
                m.direction().name(),
                format(m.rawReading()),
                format(m.computedValue()),
                m.displayValue().toPlainString(),
                m.passed(),
                m.status().name(),
                m.submittedBy(),
                m.createdAt());
    }
}

