@Service
public class IdempotencyService {
    private final IdempotencyRepository repo;
    private final ObjectMapper objectMapper;

    @Transactional
    public <T> ResponseEntity<String> execute(String requestId, String operation, String operator,
            String resource, Object params, HttpStatus status, Supplier<T> action) {
        String paramsJson = toJson(params);
        var existing = repo.findById(requestId);
        if (existing.isPresent()) {
            return replay(existing.get(), operation, operator, resource, paramsJson);
        }
        T body = action.get();
        String responseBody = toJson(body);
        repo.insert(new IdempotencyRecord(requestId, operation, operator, resource, paramsJson,
                status.value(), responseBody, Instant.now()));
        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_JSON).body(responseBody);
    }

    public ResponseEntity<String> replayAfterRace(String requestId, ...) { ... }

    private ResponseEntity<String> replay(IdempotencyRecord rec, ...) {
        if (rec.operation().equals(operation) && rec.operator().equals(operator)
                && rec.resource().equals(resource) && jsonEquals(rec.paramsJson(), paramsJson)) {
            return ResponseEntity.status(rec.responseStatus()).contentType(APPLICATION_JSON).body(rec.responseBody());
        }
        throw ApiException.conflict("IDEMPOTENCY_CONFLICT", ...);
    }
}
```

jsonEquals: parse both with objectMapper.readTree and compare.

toJson(params): params is a Map<String,Object> (TreeMap for determinism). 

